   127	async function handleUserMessage(
   128	  ws: WebSocket,
   129	  session: ChatSession,
   130	  orchestrator: ChatOrchestrator,
   131	  content: string,
   132	  signal: AbortSignal | undefined
   133	): Promise<void> {
   134	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
