   140	  const parser = new ThinkingTagParser();
   141	  const state: StreamState = {
   142	    thinkingIndex: null,
   143	    assistantIndex: null,
   144	    suppressOutput: false,
   145	    sentAssistantIndices: [],
   146	  };
