    33	}
    34	
    35	export function createServer(options: HalServerOptions): HalServer {
    36	  const basePath = options.basePath ?? '/hal';
    37	
    38	  const wss = new WebSocketServer({
    39	    noServer: true,
    40	    handleProtocols: selectSubprotocol,
    41	  });
    42	
    43	  const handleMessage = createMessageHandler(options.orchestrator);
    44	  const examplePrompts = options.toolRegistry?.getExamplePrompts() ?? [];
    45	
    46	  const deps = {
    47	    wsAuth: options.wsAuth,
    48	    sessionStore: options.sessionStore,
    49	    handleMessage,
    50	    basePath,
    51	    onConnect: options.onConnect,
    52	    onDisconnect: options.onDisconnect,
    53	    resume: options.resume,
    54	  };
    55	
    56	  const handleUpgrade = createUpgradeHandler(wss, deps);
    57	  const handleConnection = createConnectionHandler(deps, examplePrompts);
    58	
    59	  const server = http.createServer(options.app);
    60	
    61	  server.on('upgrade', (request, socket, head) => {
    62	    handleUpgrade(request, socket, head);
    63	  });
    64	
    65	  wss.on('connection', ws => {
    66	    handleConnection(ws as ExtWebSocket);
    67	  });
    68	
    69	  const heartbeatMs = options.heartbeatIntervalMs ?? 30_000;
    70	
    71	  const heartbeatInterval = setInterval(() => {
    72	    wss.clients.forEach(ws => {
    73	      const extWs = ws as ExtWebSocket;
    74	      if (!extWs.isAlive) {
    75	        extWs.terminate();
    76	        return;
    77	      }
    78	      extWs.isAlive = false;
    79	      extWs.ping();
    80	    });
    81	  }, heartbeatMs);
    82	
    83	  // The listening socket should hold the process open, not the heartbeat: an engine never started must not.
    84	  heartbeatInterval.unref();
    85	
    86	  wss.on('close', () => clearInterval(heartbeatInterval));
    87	
    88	  return {
    89	    server,
    90	    wss,
    91	    start: (port?: number) =>
    92	      new Promise<void>((resolve, reject) => {
    93	        // Refused before the handlers are touched: `listen` throws on a running server, and the swap below stripped its handler.
    94	        if (server.listening) {
    95	          reject(new Error('HAL Engine is already started'));
    96	          return;
    97	        }
    98	
    99	        // ?? not ||, so a configured port 0 means "let the OS choose" rather than 8086.
   100	        const p = port ?? options.port ?? (Number(process.env.PORT) || 8086);
   101	
   102	        // Without this an EADDRINUSE settles nothing and takes the process down as an unhandled event.
   103	        const onError = (error: Error) => reject(error);
   104	        server.once('error', onError);
   105	
   106	        // A listener left from a previous start would report this bind failure as a running server breaking.
   107	        server.removeListener('error', logLateError);
   108	
   109	        server.listen(p, () => {
   110	          server.removeListener('error', onError);
   111	
   112	          // Past the listen window nothing is listening, and an 'error' with no handler ends the process.
   113	          server.on('error', logLateError);
   114	
   115	          // The bound port, not the requested one: a configured 0 means the OS chose it.
   116	          log.info('server', 'HAL Engine started', {port: boundPort(server, p)});
   117	          resolve();
   118	        });
   119	      }),
   120	    stop: () =>
   121	      new Promise<void>((resolve, reject) => {
   122	        wss.clients.forEach(ws => ws.close(1001, 'Server shutting down'));
   123	        wss.close();
   124	        clearInterval(heartbeatInterval);
   125	
   126	        // Nothing to close after a refused start or a second stop: `close` would reject for a server that never ran.
   127	        if (!server.listening) {
   128	          resolve();
   129	          return;
   130	        }
   131	        server.close(err => (err ? reject(err) : resolve()));
   132	      }),
   133	  };
   134	}
   135	
   136	// A running server's error is a condition to report, not a reason to exit; the consumer decides what to do.
   137	function logLateError(error: Error): void {
   138	  log.error('server', 'server error after start', {error: error.message});
   139	}
   140	
   141	function boundPort(server: http.Server, requested: number): number {
   142	  const address = server.address();
   143	  return typeof address === 'object' && address !== null ? address.port : requested;
   144	}

