     1	import type {ChatSession} from './session.js';
     2	
     3	/** A value a store may return directly or resolve to, so a database-backed member needs no new interface. */
     4	export type Awaitable<T> = T | Promise<T>;
     5	
     6	export interface BaseSession {
     7	  sessionId: string;
     8	  userId: string | number;
     9	}
    10	
    11	/** What a store knows of a session id. `expired` carries the owner's id, so ownership can be checked, and never the conversation. */
    12	export type SessionLookup<T extends BaseSession = ChatSession> =
    13	  {status: 'active'; session: T} | {status: 'expired'; userId: string | number} | {status: 'missing'};
    14	
    15	/** What a conversation list needs of one session: never its entries, and never its credentials. */
    16	export interface SessionSummary {
    17	  sessionId: string;
    18	  createdAt: Date;
    19	  updatedAt: Date;
    20	  entryCount: number;
    21	}
    22	
    23	/** Where a page of conversations resumes from: the last row the caller saw, which a `SessionSummary` satisfies. */
    24	export interface SessionCursor {
    25	  /** A `Date`, an ISO string or an epoch number, so a row that went through JSON still pages (specs/hal-engine-conversation-list/spec.md). */
    26	  updatedAt: Date | string | number;
    27	  sessionId: string;
    28	}
    29	
    30	/** A window onto a user's conversations, newest activity first; `before` pages down that same order. */
    31	export interface SessionListOptions {
    32	  limit?: number;
    33	  before?: SessionCursor;
    34	}
    35	
    36	export interface SessionCreateOptions {
    37	  authHeaders?: ChatSession['authHeaders'];
    38	  workspaceId?: string | number;
    39	}
    40	
    41	export interface SessionStore<T extends BaseSession = ChatSession> {
    42	  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): Awaitable<T>;
    43	  get(sessionId: string): Awaitable<T | undefined>;
    44	  delete(sessionId: string): Awaitable<boolean>;
    45	  count(): Awaitable<number>;
    46	  clear(): Awaitable<void>;
    47	  /** Drops a session the client never received, without erasing anything a consumer would want kept. */
    48	  evict?(sessionId: string): Awaitable<boolean>;
    49	  /** Write signal: fires once per processed user message; failures are swallowed (specs/hal-engine-session-write-signal/spec.md). */
    50	  save?(session: T): Awaitable<void>;
    51	  /** Summaries of the user's conversations, newest activity first, so a client can offer a list of them (specs/hal-engine-conversation-list/spec.md). */
    52	  listFor?(userId: string | number, options?: SessionListOptions): Awaitable<SessionSummary[]>;
    53	  /** The user's most recently active session the store still holds, so a connect that names none can continue it (specs/hal-engine-session-resume/spec.md). */
    54	  latestFor?(userId: string | number): Awaitable<T | undefined>;
    55	  /** Tells an expired session from a missing one; `missing` is always a permitted answer, and a store without it behaves as `get` (specs/hal-engine-session-resume/spec.md). */
    56	  lookup?(sessionId: string): Awaitable<SessionLookup<T>>;
    57	}
